insert into difficulties (key, label, seconds_per_question) values ('basico', 'Básico', 60) on conflict (key) do update set label = excluded.label, seconds_per_question = excluded.seconds_per_question;
insert into difficulties (key, label, seconds_per_question) values ('medio', 'Medio', 90) on conflict (key) do update set label = excluded.label, seconds_per_question = excluded.seconds_per_question;
insert into difficulties (key, label, seconds_per_question) values ('experto', 'Experto', 180) on conflict (key) do update set label = excluded.label, seconds_per_question = excluded.seconds_per_question;
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('basico-f1', 'basico', 1, 'seq_explicit_terms', 'Términos de una sucesión explícita', 'Pedir tres términos consecutivos y $a_k$.', 'a_n=pn+q.', '$p\neq0$, $1\leq k\leq12$ y $|a_k|\leq40$.', '[{"name": "p", "kind": "int"}, {"name": "q", "kind": "int"}, {"name": "k", "kind": "int"}]', '[{"raw": ["2", "1", "8"], "values": [2, 1, 8]}, {"raw": ["3", "-2", "7"], "values": [3, -2, 7]}, {"raw": ["-2", "9", "6"], "values": [-2, 9, 6]}, {"raw": ["4", "-3", "5"], "values": [4, -3, 5]}]', NULL, '$a_k=pk+q$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('basico-f2', 'basico', 2, 'seq_pattern_recognition', 'Reconocimiento de patrón', 'Mostrar los primeros cuatro términos y pedir el término general y $a_k$.', 'a_n=\frac{n+r}{n+s}.', '$r,s\in\mathbb Z$, $s\geq1$, $r\neq s$, $5\leq k\leq12$.', '[{"name": "r", "kind": "int"}, {"name": "s", "kind": "int"}, {"name": "k", "kind": "int"}]', '[{"raw": ["1", "3", "8"], "values": [1, 3, 8]}, {"raw": ["2", "5", "7"], "values": [2, 5, 7]}, {"raw": ["3", "4", "10"], "values": [3, 4, 10]}, {"raw": ["-1", "2", "9"], "values": [-1, 2, 9]}]', NULL, 'mantener denominadores positivos y menores que $16$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('basico-f3', 'basico', 3, 'seq_explicit_to_recursive', 'De forma explícita a recursiva', 'Pedir $b_1$, la recurrencia y un término posterior.', 'b_n=a_1+(n-1)d.', '$a_1,d\in\mathbb Z$, $d\neq0$, $|d|\leq5$; usar $b_{n+1}=b_n+d$.', '[{"name": "a1", "kind": "int"}, {"name": "d", "kind": "int"}, {"name": "k", "kind": "int"}]', '[{"raw": ["3", "2", "9"], "values": [3, 2, 9]}, {"raw": ["7", "-1", "10"], "values": [7, -1, 10]}, {"raw": ["-2", "3", "8"], "values": [-2, 3, 8]}, {"raw": ["10", "-2", "7"], "values": [10, -2, 7]}]', NULL, '$b_k=a_1+(k-1)d$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('basico-f4', 'basico', 4, 'seq_immediate_monotonicity', 'Monotonía inmediata', 'Pedir decidir si la sucesión es creciente o decreciente mediante $c_{n+1}-c_n$.', 'c_n=pn+q.', '$p\in\{-4,-3,-2,2,3,4\}$ y $|q|\leq6$.', '[{"name": "p", "kind": "int"}, {"name": "q", "kind": "int"}]', '[]', '{"p": [-4, -3, -2, 2, 3, 4], "q": {"min": -6, "max": 6, "int": true}}', '\[ c_{n+1}-c_n=p. \] Si $p>0$ es estrictamente creciente; si $p<0$ es estrictamente decreciente.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('basico-f5', 'basico', 5, 'seq_elementary_bound', 'Acotación elemental', 'Pedir demostrar una cota superior y encontrar el menor término.', 'd_n=L-\frac{m}{n+r}.', '$L,m,r\in\mathbb N$, $1\leq m\leq6$, $0\leq r\leq3$ y $m$ múltiplo de $r+1$ cuando se desee un primer término entero.', '[{"name": "L", "kind": "int"}, {"name": "m", "kind": "int"}, {"name": "r", "kind": "int"}]', '[{"raw": ["4", "2", "1"], "values": [4, 2, 1]}, {"raw": ["5", "3", "2"], "values": [5, 3, 2]}, {"raw": ["6", "4", "1"], "values": [6, 4, 1]}, {"raw": ["3", "2", "0"], "values": [3, 2, 0]}]', NULL, '$d_1=L-m/(r+1)$ y $d_n<L$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('basico-f6', 'basico', 6, 'seq_direct_algebraic_limit', 'Límite algebraico directo', 'Pedir calcular el límite dividiendo por $n$.', 'e_n=\frac{an+b}{cn+d}.', '$a,c\in\mathbb N$, $c\neq0$, $|b|,|d|\leq5$, $cn+d>0$ para $n\geq1$ y $a/c$ entero o fracción irreducible sencilla.', '[{"name": "a", "kind": "int"}, {"name": "b", "kind": "int"}, {"name": "c", "kind": "int"}, {"name": "d", "kind": "int"}]', '[{"raw": ["2", "1", "1", "3"], "values": [2, 1, 1, 3]}, {"raw": ["3", "-1", "2", "2"], "values": [3, -1, 2, 2]}, {"raw": ["4", "3", "2", "1"], "values": [4, 3, 2, 1]}, {"raw": ["5", "-2", "3", "4"], "values": [5, -2, 3, 4]}]', NULL, '$\displaystyle\lim e_n=a/c$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('basico-f7', 'basico', 7, 'seq_guided_convergent_recurrence', 'Recurrencia convergente guiada', 'Pedir calcular tres términos, conjeturar monotonía y hallar el límite.', 'x_1=u,\qquad x_{n+1}=\frac{x_n+L}{2}.', '$u,L\in\mathbb Z$, $u\neq L$, $|u-L|\in\{2,4,8\}$. Si $u<L$, la sucesión es creciente; si $u>L$, es decreciente.', '[{"name": "u", "kind": "int"}, {"name": "L", "kind": "int"}]', '[{"raw": ["0", "4"], "values": [0, 4]}, {"raw": ["1", "5"], "values": [1, 5]}, {"raw": ["8", "4"], "values": [8, 4]}, {"raw": ["10", "2"], "values": [10, 2]}]', NULL, 'límite $L$ y fórmula $x_n=L+(u-L)2^{-(n-1)}$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('medio-f1', 'medio', 1, 'seq_alternating_pattern', 'Patrón alternante y cálculo de términos', 'Pedir cuatro términos, uno posterior y explicar el efecto de $h$.', 'a_n=(-1)^{n+h}\frac{pn+q}{n+r},\qquad h\in\{0,1\}.', '$p\in\{2,3,4\}$, $|q|\leq4$, $r\in\{1,2,3,4\}$, $pn+q>0$ para $n\geq1$ y $5\leq k\leq10$.', '[{"name": "p", "kind": "int"}, {"name": "q", "kind": "int"}, {"name": "r", "kind": "int"}, {"name": "h", "kind": "int"}, {"name": "k", "kind": "int"}]', '[{"raw": ["2", "3", "4", "1", "8"], "values": [2, 3, 4, 1, 8]}, {"raw": ["3", "1", "2", "0", "7"], "values": [3, 1, 2, 0, 7]}, {"raw": ["4", "-1", "3", "1", "6"], "values": [4, -1, 3, 1, 6]}, {"raw": ["2", "1", "1", "0", "9"], "values": [2, 1, 1, 0, 9]}]', NULL, NULL)
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('medio-f2', 'medio', 2, 'seq_explicit_recursive_conversion', 'Conversión explícita-recursiva', 'Pedir una recurrencia de primer orden y comprobarla.', 'b_n=L+Cq^{n-1}.', '$q\in\{2,3,-2\}$, $C\neq0$, $|C|\leq4$, $|L|\leq5$; usar \[ b_{n+1}=q b_n+(1-q)L,\qquad b_1=L+C. \]', '[{"name": "L", "kind": "int"}, {"name": "C", "kind": "int"}, {"name": "q", "kind": "int"}]', '[{"raw": ["3", "2", "2"], "values": [3, 2, 2]}, {"raw": ["-1", "3", "2"], "values": [-1, 3, 2]}, {"raw": ["2", "-1", "3"], "values": [2, -1, 3]}, {"raw": ["1", "2", "-2"], "values": [1, 2, -2]}]', NULL, NULL)
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('medio-f3', 'medio', 3, 'seq_rational_monotonicity', 'Monotonía racional', 'Pedir determinar la monotonía mediante diferencia.', 'c_n=\frac{An+B}{Cn+D}.', '$C>0$, $Cn+D>0$ para $n\geq1$, $AD-BC\neq0$ y $|A|,|B|,|C|,|D|\leq6$.', '[{"name": "A", "kind": "int"}, {"name": "B", "kind": "int"}, {"name": "C", "kind": "int"}, {"name": "D", "kind": "int"}]', '[{"raw": ["4", "-1", "2", "3"], "values": [4, -1, 2, 3]}, {"raw": ["3", "2", "2", "5"], "values": [3, 2, 2, 5]}, {"raw": ["2", "5", "3", "1"], "values": [2, 5, 3, 1]}, {"raw": ["5", "1", "2", "4"], "values": [5, 1, 2, 4]}]', NULL, '\[ c_{n+1}-c_n=\frac{AD-BC}{(Cn+D)(Cn+C+D)}. \]')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('medio-f4', 'medio', 4, 'seq_horizontal_asymptote_bound', 'Acotación por una asíntota horizontal', 'Pedir monotonía, una cota alcanzada y otra no alcanzada.', 'd_n=L+\frac{K}{n+r}.', '$K\neq0$, $r\geq0$ y $n+r>0$. Si $K>0$, decrece hacia $L$; si $K<0$, crece hacia $L$.', '[{"name": "L", "kind": "int"}, {"name": "K", "kind": "int"}, {"name": "r", "kind": "int"}]', '[{"raw": ["3", "4", "1"], "values": [3, 4, 1]}, {"raw": ["5", "-3", "2"], "values": [5, -3, 2]}, {"raw": ["-1", "2", "1"], "values": [-1, 2, 1]}, {"raw": ["2", "-4", "3"], "values": [2, -4, 3]}]', NULL, 'extremo alcanzado $d_1=L+K/(r+1)$; límite $L$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('medio-f5', 'medio', 5, 'seq_rationalizable_limit', 'Límite racionalizable', 'Pedir racionalizar y calcular el límite.', 'e_n=\sqrt{p^2n^2+qn+r}-pn.', '$p\in\{1,2,3,4\}$, $q$ múltiplo de $2p$ para obtener $q/(2p)$ entero o semientero, y el radicando debe ser positivo para $n\geq1$.', '[{"name": "p", "kind": "int"}, {"name": "q", "kind": "int"}, {"name": "r", "kind": "int"}]', '[{"raw": ["1", "4", "1"], "values": [1, 4, 1]}, {"raw": ["2", "4", "3"], "values": [2, 4, 3]}, {"raw": ["3", "6", "2"], "values": [3, 6, 2]}, {"raw": ["4", "8", "1"], "values": [4, 8, 1]}]', NULL, '$\displaystyle\lim e_n=q/(2p)$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('medio-f6', 'medio', 6, 'seq_affine_convergent_recurrence', 'Recurrencia afín convergente', 'Pedir demostrar monotonía, acotación y convergencia.', 'x_1=u,\qquad x_{n+1}=\rho x_n+(1-\rho)L.', '$0<\rho<1$; usar $u<L$ para crecimiento y $u>L$ para decrecimiento.', '[{"name": "rho", "kind": "rational"}, {"name": "L", "kind": "int"}, {"name": "u", "kind": "int"}]', '[{"raw": ["\\tfrac12", "4", "0"], "values": [0.5, 4, 0]}, {"raw": ["\\tfrac13", "3", "0"], "values": [0.3333333333333333, 3, 0]}, {"raw": ["\\tfrac14", "2", "6"], "values": [0.25, 2, 6]}, {"raw": ["\\tfrac23", "5", "8"], "values": [0.6666666666666666, 5, 8]}]', NULL, '$x_n=L+(u-L)\rho^{n-1}$ y $\lim x_n=L$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('medio-f7', 'medio', 7, 'seq_sandwich_theorem', 'Teorema del sándwich', 'Usar $\varepsilon_n=(-1)^n$, $\sin n$ o $\cos(n^2)$ y pedir justificar el límite.', '\[ y_n=\varepsilon_n\frac{an+b}{n^2+c}, \qquad |\varepsilon_n|\leq1. \]', '$a>0$, $b,c\geq0$, $a,b,c\leq6$.', '[{"name": "eps", "kind": "symbol", "symbols": {"alternating": "(-1)^n", "sin": "\\sin n", "cos_sq": "\\cos(n^2)", "alternating_shift": "(-1)^{n+1}"}}, {"name": "a", "kind": "int"}, {"name": "b", "kind": "int"}, {"name": "c", "kind": "int"}]', '[{"raw": ["(-1)^n", "2", "3", "1"], "values": ["alternating", 2, 3, 1]}, {"raw": ["\\sin n", "3", "1", "2"], "values": ["sin", 3, 1, 2]}, {"raw": ["\\cos(n^2)", "4", "2", "3"], "values": ["cos_sq", 4, 2, 3]}, {"raw": ["(-1)^{n+1}", "5", "1", "4"], "values": ["alternating_shift", 5, 1, 4]}]', NULL, '\[ |y_n|\leq\frac{an+b}{n^2+c}\longrightarrow0. \]')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('experto-f1', 'experto', 1, 'seq_reconstruction_from_differences', 'Reconstrucción desde diferencias', 'Pedir hallar una fórmula explícita y verificarla por inducción.', 'a_{n+1}-a_n=pn+q,\qquad a_1=r.', '$p\neq0$, $|p|\leq4$, $|q|\leq5$, $|r|\leq6$. Usar \[ a_n=r+\frac{p(n-1)n}{2}+q(n-1). \]', '[{"name": "p", "kind": "int"}, {"name": "q", "kind": "int"}, {"name": "r", "kind": "int"}]', '[{"raw": ["2", "1", "3"], "values": [2, 1, 3]}, {"raw": ["3", "-1", "2"], "values": [3, -1, 2]}, {"raw": ["-2", "5", "1"], "values": [-2, 5, 1]}, {"raw": ["4", "-3", "-1"], "values": [4, -3, -1]}]', NULL, NULL)
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('experto-f2', 'experto', 2, 'seq_second_order_recurrence', 'Recurrencia de segundo orden', 'Pedir construir la recurrencia, calcular datos iniciales y demostrar equivalencia.', 'b_n=A\alpha^n+B\beta^n.', '$\alpha,\beta\in\{-2,-1,2,3,4\}$, $\alpha\neq\beta$, $A,B\in\{-3,-2,-1,1,2,3\}$ y términos iniciales de valor absoluto menor que $50$.', '[{"name": "A", "kind": "int"}, {"name": "B", "kind": "int"}, {"name": "alpha", "kind": "int"}, {"name": "beta", "kind": "int"}]', '[{"raw": ["1", "-1", "3", "2"], "values": [1, -1, 3, 2]}, {"raw": ["2", "-1", "2", "-1"], "values": [2, -1, 2, -1]}, {"raw": ["1", "2", "2", "-2"], "values": [1, 2, 2, -2]}, {"raw": ["-1", "2", "3", "1"], "values": [-1, 2, 3, 1]}]', NULL, '\[ b_{n+2}=(\alpha+\beta)b_{n+1}-\alpha\beta b_n. \]')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('experto-f3', 'experto', 3, 'seq_monotonicity_regime_change', 'Monotonía con cambio de comportamiento', 'Pedir localizar exactamente dónde crece, se mantiene o decrece.', 'c_n=\frac{p^n}{(n+q)!}.', '$p\in\{4,5,6,7\}$, $q\in\{1,2,3\}$ y $p-q-1\in\{1,2,3,4\}$.', '[{"name": "p", "kind": "int"}, {"name": "q", "kind": "int"}]', '[{"raw": ["4", "1"], "values": [4, 1]}, {"raw": ["4", "2"], "values": [4, 2]}, {"raw": ["5", "1"], "values": [5, 1]}, {"raw": ["5", "2"], "values": [5, 2]}, {"raw": ["5", "3"], "values": [5, 3]}, {"raw": ["6", "1"], "values": [6, 1]}, {"raw": ["6", "2"], "values": [6, 2]}, {"raw": ["6", "3"], "values": [6, 3]}, {"raw": ["7", "2"], "values": [7, 2]}, {"raw": ["7", "3"], "values": [7, 3]}]', NULL, '\[ \frac{c_{n+1}}{c_n}=\frac{p}{n+q+1}. \] Hay igualdad cuando $n=p-q-1$; evitar esa igualdad si se desea solo crecimiento y decrecimiento eligiendo $p$ no entero.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('experto-f4', 'experto', 4, 'seq_root_monotonicity_bound', 'Monotonía y acotación de una raíz', 'Pedir racionalizar, probar monotonía, determinar cotas y anticipar el límite.', 'd_n=\sqrt{n+s}-\sqrt{n+r},\qquad s>r.', '$r\geq0$, $1\leq s-r\leq6$ y $r,s\leq8$.', '[{"name": "r", "kind": "int"}, {"name": "s", "kind": "int"}]', '[{"raw": ["0", "3"], "values": [0, 3]}, {"raw": ["1", "5"], "values": [1, 5]}, {"raw": ["2", "6"], "values": [2, 6]}, {"raw": ["4", "7"], "values": [4, 7]}]', NULL, '\[ d_n=\frac{s-r}{\sqrt{n+s}+\sqrt{n+r}}, \] por lo que es positiva, decreciente y converge a $0$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('experto-f5', 'experto', 5, 'seq_hidden_dominant_power_limit', 'Límite con potencia dominante oculta', 'Pedir factorizar la potencia dominante y calcular el límite.', '\[ e_n=\ln\!\left(A\lambda^n+B\mu^n\right)-n\ln\lambda, \qquad \lambda>\mu>0. \]', '$A,B\in\{1,2,3,4\}$, $(\lambda,\mu)$ en $\{(3,2),(4,2),(4,3),(5,2)\}$ y argumentos positivos.', '[{"name": "A", "kind": "int"}, {"name": "B", "kind": "int"}, {"name": "lambda", "kind": "int"}, {"name": "mu", "kind": "int"}]', '[{"raw": ["1", "1", "3", "2"], "values": [1, 1, 3, 2]}, {"raw": ["1", "1", "4", "2"], "values": [1, 1, 4, 2]}, {"raw": ["1", "1", "4", "3"], "values": [1, 1, 4, 3]}, {"raw": ["1", "1", "5", "2"], "values": [1, 1, 5, 2]}, {"raw": ["1", "2", "3", "2"], "values": [1, 2, 3, 2]}, {"raw": ["1", "2", "4", "2"], "values": [1, 2, 4, 2]}, {"raw": ["1", "2", "4", "3"], "values": [1, 2, 4, 3]}, {"raw": ["1", "2", "5", "2"], "values": [1, 2, 5, 2]}, {"raw": ["1", "3", "3", "2"], "values": [1, 3, 3, 2]}, {"raw": ["1", "3", "4", "2"], "values": [1, 3, 4, 2]}, {"raw": ["1", "3", "4", "3"], "values": [1, 3, 4, 3]}, {"raw": ["1", "3", "5", "2"], "values": [1, 3, 5, 2]}, {"raw": ["1", "4", "3", "2"], "values": [1, 4, 3, 2]}, {"raw": ["1", "4", "4", "2"], "values": [1, 4, 4, 2]}, {"raw": ["1", "4", "4", "3"], "values": [1, 4, 4, 3]}, {"raw": ["1", "4", "5", "2"], "values": [1, 4, 5, 2]}, {"raw": ["2", "1", "3", "2"], "values": [2, 1, 3, 2]}, {"raw": ["2", "1", "4", "2"], "values": [2, 1, 4, 2]}, {"raw": ["2", "1", "4", "3"], "values": [2, 1, 4, 3]}, {"raw": ["2", "1", "5", "2"], "values": [2, 1, 5, 2]}, {"raw": ["2", "2", "3", "2"], "values": [2, 2, 3, 2]}, {"raw": ["2", "2", "4", "2"], "values": [2, 2, 4, 2]}, {"raw": ["2", "2", "4", "3"], "values": [2, 2, 4, 3]}, {"raw": ["2", "2", "5", "2"], "values": [2, 2, 5, 2]}, {"raw": ["2", "3", "3", "2"],