insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('experto-f6', 'experto', 6, 'seq_heron_iteration', 'Iteración de Herón', 'Pedir probar positividad, acotación, monotonía y convergencia.', 'x_1=u,\qquad x_{n+1}=\frac12\left(x_n+\frac{Q}{x_n}\right).', '$Q$ no cuadrado perfecto, $Q\in\{2,3,5,6,7\}$ y $u$ entero con $u>\sqrt Q$, procurando $u^2-Q\leq6$.', '[{"name": "Q", "kind": "int"}, {"name": "u", "kind": "int"}]', '[{"raw": ["2", "2"], "values": [2, 2]}, {"raw": ["3", "2"], "values": [3, 2]}, {"raw": ["5", "3"], "values": [5, 3]}, {"raw": ["6", "3"], "values": [6, 3]}, {"raw": ["7", "3"], "values": [7, 3]}]', NULL, 'para $n\geq2$, $x_n\geq\sqrt Q$; la sucesión decrece y $\lim x_n=\sqrt Q$.')
insert into families (id, level_key, family_index, generator_key, title, prompt, template_latex, conditions, params_json, tuples_json, domain_json, control_latex) values ('experto-f7', 'experto', 7, 'seq_subsequence_convergence', 'Convergencia o divergencia mediante subsucesiones', 'Pedir estudiar las subsucesiones pares e impares y decidir convergencia.', 'y_n=A+B(-1)^n+\frac{C}{n}.', '$A,C\in\mathbb Z$, $B\in\{-3,-2,-1,1,2,3\}$, $|A|,|C|\leq5$. Mantener $B\neq0$ para garantizar dos límites distintos.', '[{"name": "A", "kind": "int"}, {"name": "B", "kind": "int"}, {"name": "C", "kind": "int"}]', '[{"raw": ["1", "1", "2"], "values": [1, 1, 2]}, {"raw": ["2", "-1", "3"], "values": [2, -1, 3]}, {"raw": ["-1", "2", "1"], "values": [-1, 2, 1]}, {"raw": ["0", "-2", "5"], "values": [0, -2, 5]}]', NULL, '\[ y_{2n}\longrightarrow A+B, \qquad y_{2n-1}\longrightarrow A-B; \] por tanto, $(y_n)$ diverge.')
